// @whimtex-effect Samples/Master Tint
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param color _Tint = (1, 1, 1, 1)

float4 ApplyFX(float2 uv,float4 color){return float4(color.rgb*_Tint.rgb,color.a*_Opacity*_Tint.a);}

// @whimtex-effect Samples/Gain
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1] // Blend between the original and corrected colors.
// @group
// @param float _Gain = 1 [0 .. ~4]
// @param color _Tint = (0, 0.9883721, 1, 1)
// @endgroup


float4 ApplyFX(float2 uv, float4 color)
{
    float4 correctedColor = float4(color.rgb * _Tint.rgb * _Gain, color.a * _Tint.a);
	return lerp(color, correctedColor, _Opacity);
}

// @whimtex-effect Samples/Lightning Path
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param float _Width = 0.012 [0.0005 .. 0.012]
// @param float _Bend = 0.143 [0 .. 0.3]
// @param float _Seed = 22.7 [0 .. 100]
// @param float _Glow = 0.53 [0 .. 1]
// @param float _GlowWidth = 1.8 [1 .. 20]

float PathX(float t){return .5+_Bend*(.68*sin(t*9+_Seed)+.28*sin(t*24+1.2)+.12*sin(t*63+2));}
float4 ApplyFX(float2 uv,float4 color){
    float d=1;float along=0;
    for(int i=0;i<96;i++){
        float t=i/96.0;float s=(i+1)/96.0;
        float2 a=float2(PathX(t),.065+t*.87);float2 b=float2(PathX(s),.065+s*.87);
        float2 ab=b-a;float h=saturate(dot(uv-a,ab)/dot(ab,ab));
        float distance=length(uv-a-ab*h);
        if(distance<d){d=distance;along=lerp(t,s,h);}
    }
    float width=_Width*(.8+.2*sin(along*57+_Seed));
    float aa=max(fwidth(d),.0003);
    float alpha=1-smoothstep(width*.4,width+aa,d);
    alpha+=_Glow*exp(-d/max(width*_GlowWidth,.0001));
    alpha*=smoothstep(.045,.085,uv.y)*(1-smoothstep(.915,.955,uv.y));
    return float4(1,1,1,saturate(alpha)*_Opacity);
}

